//Real5aa60,5ab40,5b470/5b3c0 and5ba10.59c60/52810/52960 are
//recorded route leaves; occupancy storage, signed geometry and peerwrites real.
import ghidra.app.script.GhidraScript;import ghidra.app.emulator.EmulatorHelper;import java.io.*;
public class ZNov04OccupancyOracle extends GhidraScript{static final long RET=0x12345000L,S=0x7fff0000L,U=0x5e30c8L,H=0x1000000L,P=H+1024,R=0x60ec00L;long read(EmulatorHelper e,long a,int n){byte[]b=e.readMemory(toAddr(a),n);long v=0;for(int i=0;i<n;i++)v|=(b[i]&255L)<<(8*i);return v;}void put(EmulatorHelper e,long a,int n,long v)throws Exception{e.writeMemoryValue(toAddr(a),n,v);}void back(EmulatorHelper e)throws Exception{long sp=e.readRegister("ESP").longValue(),ret=read(e,sp,4);e.writeRegister("ESP",sp+4);if(!e.run(toAddr(ret),null,monitor))throw new Exception(e.getLastError());}int hash(byte[]bytes){int h=0x811c9dc5;for(byte b:bytes)h=(h^(b&255))*16777619;return h;}
 public void run()throws Exception{try(PrintWriter out=new PrintWriter(getScriptArgs()[0])){for(int mode=0;mode<4;mode++)for(int s=0;s<256;s++){EmulatorHelper e=new EmulatorHelper(currentProgram);try{e.writeMemory(toAddr(U),new byte[25*192]);e.writeMemory(toAddr(H),new byte[2048]);e.writeMemory(toAddr(R),new byte[216]);byte[]terrain=new byte[16384];for(int j=0;j<terrain.length;j++)terrain[j]=(byte)((j*3+s*17)%67|(s%2*128));e.writeMemory(toAddr(0x58aaaa),terrain);byte[]w=new byte[44];for(int j=0;j<44;j++)w[j]=(byte)(s*19+j*7);long hw=s%3==0?0x62dc08L:H;e.writeMemory(toAddr(hw),w);for(int j=0;j<128;j++)put(e,P+j,1,(s+j)%11==0?255:j%5);put(e,U+8,4,s%3==0?(s%2==0?0:-1):H);put(e,U+0x18,4,P);put(e,U+44,2,519+s%3);put(e,U+46,2,516+s/3%3);put(e,U+0x7c,1,s%2);put(e,U+0x35,1,9);put(e,U+0x31,1,s%5==0?0:4);put(e,U+0x71,1,s*17);put(e,U+0x6f,1,s*23);put(e,U+0x70,1,mode==2?1:s%7==0?255:1);put(e,U+0x72,2,new int[]{0,1,2,17,-1,-32768}[s/3%6]);put(e,U+0x5f,1,0);put(e,0x632194,4,R+144);long peer=U+192;put(e,peer+0x7c,1,s%3==0?1:0);put(e,peer+0x31,1,s%7==0?0:4);put(e,peer+0x5f,1,s%13==0?255:1);put(e,peer+0x6f,1,s*13);int dx=new int[]{-33,-32,-31,0,31,32,33,-32768}[s/5%8],dy=new int[]{-33,-32,-31,0,31,32,33,-32768}[s/7%8];put(e,peer+44,2,519+s%3+dx);put(e,peer+46,2,516+s/3%3+dy);for(int j=0;j<21;j++){int slot=j+2;put(e,R+72+19+j,1,(s+j)%4==0?255:slot);put(e,U+slot*192+0x31,1,(s+j)%5==0?0:4);put(e,U+slot*192+44,2,519+s%3+dx+(j%3-1)*31);put(e,U+slot*192+46,2,516+s/3%3+dy+(j%5-2)*16);}
 for(long pc:new long[]{RET,0x459c60,0x452810,0x452960})e.setBreakpoint(toAddr(pc));e.writeRegister("ESP",S);put(e,S,4,RET);e.writeRegister("ECX",U);e.writeRegister("EDX",peer);if(!e.run(toAddr(new long[]{0x45aa60,0x45ab40,0x45b470,0x45ba10}[mode]),null,monitor))throw new Exception(e.getLastError());int resume=0,checks=0,trace=0x811c9dc5,n=0;while(e.readRegister("EIP").longValue()!=RET){if(++n>10)throw new Exception("loop");long pc=e.readRegister("EIP").longValue();if(pc==0x459c60){long sp=e.readRegister("ESP").longValue();for(int v:new int[]{1,(short)e.readRegister("EDX").intValue(),(short)read(e,sp+4,4)})trace=(trace^v)*16777619;}else if(pc==0x452810){resume++;trace=(trace^2)*16777619;e.writeRegister("EAX",resume>s%3?0:1);}else{checks++;trace=(trace^3)*16777619;e.writeRegister("EAX",checks<=s/3%3?1:0);}back(e);}
 out.print("{\"mode\":"+mode+",\"scenario\":"+s+",\"result\":"+(mode==2?(e.readRegister("EAX").intValue()&255):0)+",\"resume\":"+resume+",\"checks\":"+checks+",\"trace\":"+(trace&0xffffffffL));for(int[]f:new int[][]{{0x35,1},{0x71,1},{0x6f,1},{0x70,1},{0x72,2}}){long v=read(e,U+f[0],f[1]);if(f[1]==2)v=(short)v;out.print(",\"u"+f[0]+"\":"+v);}out.println(",\"peer6f\":"+read(e,peer+0x6f,1)+",\"context\":"+((read(e,0x632194,4)-R)/72)+",\"hardware\":"+(hash(e.readMemory(toAddr(hw),44))&0xffffffffL)+",\"terrain\":"+(hash(e.readMemory(toAddr(0x58aaaa),16384))&0xffffffffL)+"}");}finally{e.dispose();}}}}
}
